const fs = require('node:fs');
const path = require('node:path');
const { load } = require('./test-growth.cjs');
const data = load('data/growth/index.ts');
const publication = load('lib/growth/publication.ts');
const geo = load('lib/growth/geo.ts');
const lines = [
  '# Qognition growth-site coverage and data lineage',
  '',
  'Snapshot: 2026-09-24. Generated by `node scripts/report-growth-coverage.cjs`.',
  '',
  '## Publication contract',
  '',
  '- Registry coverage is distinct from public pages and index eligibility.',
  '- `draft` and `review` marketing records do not resolve as public pages. Unknown combinations return 404.',
  '- Navigation and indexing are independent flags on a published record.',
  '- Indexable publication requires editorial context and a reviewed date. Sitemap dates use actual content dates.',
  '- Deep subniche briefs are published for human browsing but currently noindex. They contain a distinct buyer focus and evidence checklist; they need deeper original examples before broad search expansion.',
  '- Geographic record profiles are server-rendered, noindex reference utilities. They are not generated local agency landing pages or claims of a local office.',
  '- Source-derived geographic history is retained. Historical, abandoned and destroyed populated-place records are excluded by default from catalog results.',
  '',
  '## Current authored coverage',
  '',
  `- ${data.growthSectors.length} sector hubs; ${data.growthNiches.filter(n=>!n.parentId).length} niches; ${data.growthNiches.filter(n=>n.parentId).length} subniches.`,
  `- ${data.growthPillars.length} pillar pages and ${data.growthServices.length} canonical service pages.`,
  `- Every existing subservice is mapped: ${data.legacyGrowthServiceMappings.length}/${data.legacyGrowthServiceMappings.length}. Historical URLs are preserved; mapping does not approve unsupported copy on legacy routes.`,
  `- ${data.growthPrograms.length} distinct pilot program briefs. These are authored planning approaches, not customer results or verified search-volume claims.`,
  `- ${publication.getPublishedGrowthPages().length} manifest-published pages; ${publication.getGrowthSitemapEntries().length} indexable. Database-driven noindex place profiles are additional and not enumerated in the sitemap.`,
  '',
  '## Geographic lineage',
  '',
  `Full country dumps imported for ${geo.geographyCoverage.countries} selected markets, retaining every P (populated place) and A (administrative area) source record without a population threshold.`,
  '',
  `Totals: ${geo.geographyCoverage.records.toLocaleString('en-US')} records; ${geo.geographyCoverage.populatedPlaces.toLocaleString('en-US')} populated places; ${geo.geographyCoverage.administrativeAreas.toLocaleString('en-US')} administrative areas.`,
  '',
  'Source: [GeoNames country exports](https://download.geonames.org/export/dump/), [format documentation](https://download.geonames.org/export/dump/readme.txt), [CC BY 4.0](https://creativecommons.org/licenses/by/4.0/). Names and classifications may be incomplete or outdated. This is complete ingestion of the selected source classes, not a guarantee of every real-world town or region.',
  '',
  'Per-country original archive SHA256, transformed JSONL SHA256, source modified date, import timestamp and counts are retained in `data/growth/geography/manifest.json`. Compressed JSONL stays server-side and streams with bounded memory. No request parses a complete large country into memory.',
  '',
  '| Country | Source records | Populated places | Administrative areas | Imported |',
  '|---|---:|---:|---:|---|',
  ...geo.geographyManifest.countries.map(c=>`| ${c.countryCode} | ${c.sourceRecords} | ${c.populatedPlaces} | ${c.administrativeAreas} | ${c.importedAt.slice(0,10)} |`),
  '',
  'The global country candidate registry uses GeoNames `countryInfo.txt`. Countries outside the selected 17 have candidate status and no claimed GDP qualification. Ranking additional high-GDP, industry-dense markets still requires economic and commercial evidence; no fabricated GDP values are stored.',
  '',
  '## Canonical taxonomy',
  '',
];
for (const sector of data.growthSectors) {
  lines.push(`### ${sector.name}`, '');
  for (const niche of data.growthNiches.filter(n=>n.sectorId===sector.id&&!n.parentId)) {
    const children=data.growthNiches.filter(n=>n.parentId===niche.id);
    lines.push(`- ${niche.name}${children.length ? ': '+children.map(n=>n.name).join('; ') : ''}.`);
  }
  lines.push('');
}
lines.push('## Legacy subservice mapping', '', '| Existing category | Subservice | New pillar | Existing URL |', '|---|---|---|---|');
for (const item of data.legacyGrowthServiceMappings) lines.push(`| ${item.legacyCategoryName} | ${item.name} | ${item.pillarId} | ${item.legacyPath} |`);
lines.push('', '## Explicit limits and follow-through', '',
  '- “All niches” means the union of the supplied briefs plus existing retained service coverage, not every possible B2B category in the world.',
  '- China and India export plays are geographic/business-model overlays, not duplicate industries. Headquarters, customer market, language and service footprint remain separate.',
  '- Every combination is representable in the entity model; only explicitly authored/reviewed marketing combinations resolve. A complete Cartesian product is intentionally not published.',
  '- Region and city records have standalone noindex reference profiles. Dedicated indexable city/industry/service pages require an original buyer and market brief; there is no blanket promise of local search demand.',
  '- Sanity includes growth taxonomy, source and publication schemas. The checked-in manifest remains the application publication source for this release; changes in Sanity do not automatically override the code-reviewed manifest. A controlled editorial export/review is required for publishing changes.',
  '- The 11-language routing/translation registry is implemented separately. Only complete published translations receive language alternates; the English catalog is not silently advertised as translated.',
  '- No proof, office, certification, guaranteed citation or attributable revenue outcome is inferred from a taxonomy entry.',
  '- Live search-demand data, client-approved vertical proof and independently sourced market benchmarks were not supplied for every niche or place. Those remain editorial inputs for later publication waves.',
  '', '## Validation', '', '`node scripts/test-growth.cjs` checks entity uniqueness, hierarchy, all 119 subservice mappings, pilot required fields, publication/index separation, source integrity, streaming search and invalid-country rejection. Full application type/build and browser checks are managed by the integration task.', '');
const out=path.join(__dirname,'../docs/growth-coverage.md');
fs.mkdirSync(path.dirname(out),{recursive:true}); fs.writeFileSync(out, lines.join('\n'));
console.log(out);
